import{_ as a,o,c as t,a5 as c}from"./chunks/framework.BEZBAInb.js";const u=JSON.parse('{"title":"씬 기반 리소스","description":"","frontmatter":{"title":"씬 기반 리소스","order":8},"headers":[],"relativePath":"ko/latest/tutorial/core/scene-assets.md","filePath":"ko/latest/tutorial/core/scene-assets.md","lastUpdated":1788455378000}'),s={name:"ko/latest/tutorial/core/scene-assets.md"};function r(d,e,n,_,i,p){return o(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="씬-기반-리소스" tabindex="-1">씬 기반 리소스 <a class="header-anchor" href="#씬-기반-리소스" aria-label="Permalink to &quot;씬 기반 리소스&quot;">​</a></h1><p>캐릭터와 배경 항목은 <code>PackedScene</code>을 참조합니다. 씬에는 이미지, 비디오, Spine, Live2D, 셰이더 또는 사용자 노드를 넣을 수 있습니다.</p><p>캐릭터 씬은 <code>KonadoCharacterSceneBase</code>를 상속하고 <code>_apply_status(resolved_status_name, original_status_name)</code>를 재정의합니다. 상태 이름을 검증할 수 있다면 <code>_has_status</code>도 구현합니다. 지연 전환은 요청 수락 시점과 최종 적용 시점에 이를 확인할 수 있으므로 <code>_has_status</code>는 부작용이 없고 멱등이어야 합니다. 순수 텍스처를 안전하게 제공할 수 있는 씬은 <code>_get_current_status_transition_frame</code>과 <code>_get_status_transition_frame</code>을 모두 구현하여 <code>KonadoCharacterTransitionFrame</code> 기반 프리멀티플라이드 알파 블렌딩을 사용할 수 있습니다. 부작용 없는 프레임을 제공할 수 없는 Live2D, Spine, 비디오 및 사용자 씬은 안전한 페이드아웃, 상태 적용, 페이드인 경로로 자동 대체됩니다. 두 경로 모두 캐릭터 씬을 복제하지 않습니다. 설정은 <a href="./../script/actor/actor-change-state.html">액터 상태 전환</a>을 참고하세요. 무대 동작은 <code>KonadoActorMotionLayer</code> 씬에 둡니다.</p><p>상태 프레임을 요청할 때마다 새 독립 프레임을 반환해야 하며, 두 전환 끝점에 같은 가변 프레임을 재사용하면 안 됩니다.</p><p>배경 씬은 <code>KonadoBackgroundSceneBase</code>를 상속합니다. 카메라 명령을 사용하려면 고유한 이름의 <code>KonadoCameraMarker</code>를 추가하세요. 이 노드는 목표 위치와 확대/축소 값만 저장하며 실제 렌더링은 대화 템플릿의 카메라가 담당합니다. 사용자 정의 렌더링 카메라를 <code>KonadoCameraMarker</code>로 바꾸지 마세요. 기본 전환은 <code>KonadoBackgroundTransitionLayer</code>가 처리하며, 기본적으로 <code>SubViewport</code>를 통해 전체 씬을 캡처합니다. 최종 화면이 수정되지 않은 단일 원본 텍스처와 완전히 동일한 경우에만 <code>DIRECT_TEXTURE</code>를 선택하세요. 레이아웃, 변형, 카메라, 애니메이션, 머티리얼, 색조 또는 여러 그리기 노드를 사용하는 배경은 <code>VIEWPORT_CAPTURE</code>를 유지해야 합니다.</p>',5)])])}const m=a(s,[["render",r]]);export{u as __pageData,m as default};
